#include <windows.h>
#include <stdio.h>

typedef int (*MyFunctionPtr)(int, int);

int main() {
  HINSTANCE hDLL = LoadLibrary("mylib.dll");
  if (hDLL == NULL) {
    fprintf(stderr, "Failed to load library\n");
    return 1;
  }

  MyFunctionPtr myFunc = (MyFunctionPtr)GetProcAddress(hDLL, "myFunction");
  if (myFunc == NULL) {
    fprintf(stderr, "Failed to get function address\n");
    FreeLibrary(hDLL);
    return 1;
  }

  int result = myFunc(5, 3);
  printf("Result: %d\n", result);

  FreeLibrary(hDLL);
  return 0;
}
